from tools.check_msk_fidelity import requirements_for
ROOT=Path(__file__).resolve().parents[2];IDENT='ra.mri-cardiomyopathy'
URLS=['https://radiologyassistant.nl/cardiovascular/anatomy/cardiac-anatomy','https://radiologyassistant.nl/cardiovascular/cardiomyopathy/ischemic-and-non-ischemic-cardiomyopathy','https://pmc.ncbi.nlm.nih.gov/articles/PMC7066763/','https://pmc.ncbi.nlm.nih.gov/articles/PMC11084160/']
